import React from 'react';
import { useNavigate } from 'react-router-dom';
import '../styles/WelcomePage.css';

const WelcomePage = () => {
  const navigate = useNavigate();

  return (
    <div className="welcome-container">
      <div className="welcome-content">
        <h1>Welcome to SolarAI</h1>
        <p className="welcome-subtitle">Your Intelligent Solar Panel Maintenance Solution</p>

        <div className="welcome-features">
          <div className="feature-card">
            <h3>AI-Powered Maintenance</h3>
            <p>Get instant analysis of your solar panel performance and maintenance needs</p>
          </div>

          <div className="feature-card">
            <h3>Real-time Monitoring</h3>
            <p>Track your solar panel health and efficiency in real-time</p>
          </div>

          <div className="feature-card">
            <h3>Expert Support</h3>
            <p>Connect with certified technicians for professional maintenance</p>
          </div>
        </div>

        <button 
          className="dashboard-button"
          onClick={() => navigate('/dashboard')}
        >
          Go to Dashboard
        </button>
      </div>
    </div>
  );
};

export default WelcomePage;
